#include "rpg/pve.hpp"
#include <iostream>
using namespace rpg;
void check(bool x,const char* m){if(!x){throw std::runtime_error(m);}}
PveDefinition config(){PveDefinition d;d.id="ritual";d.attempt_id="one";d.boss_id="B";d.roster={{"A",Team::A,1000,100,100},{"B",Team::B,100,10,90},{"ADD",Team::B,1000,1,10}};d.roster[2].role=EntityRole::Auxiliary;for(auto& f:d.roster){f.stats.block=0;}d.rules.timing=TimingProfile::ActionBar;d.rules.combat_model=resolution::CombatModel::FunnelV1;return d;}
int main(){try{
 ScoreLedger ledger;PveEncounter ritual(config(),ledger);auto r=ritual.apply({"A",ActionType::Attack,"B"});check(r.action.accepted()&&r.attempt_finished&&r.objective_met&&ritual.battle().find("ADD")->health==1000,"boss death ends ritual with adds alive");check(!ritual.apply({"A",ActionType::Attack,"ADD"}).action.accepted()&&ledger.receipts().empty(),"no command/reward after end");
 auto window=config();window.attempt_id="score";window.mode=PveMode::ScoreAttack;window.roster[1].max_health=10000;window.rules.action_budget=ActionBudget{1,LimitOutcome::DefeatA};PveEncounter score(window,ledger);r=score.apply({"A",ActionType::Attack,"B"});check(r.attempt_finished&&r.end==PveEnd::WindowClosed&&r.score==100&&!r.objective_met,"score window closes without ritual victory");
 auto survival=config();survival.attempt_id="survival";survival.mode=PveMode::Survival;survival.boss_turn_goal=1;survival.roster[1].max_health=10000;PveEncounter survive(survival,ledger);check(survive.apply({"A",ActionType::Attack,"B"}).action.accepted(),"player turn");r=survive.apply({"B",ActionType::Attack,"A"});check(r.attempt_finished&&r.objective_met&&r.end==PveEnd::SurvivalReached,"boss-turn survival goal");
 Definition owner{"A",Team::A,10,1,100},summon{"S",Team::A,1000,1,10},boss{"B",Team::B,1000,100,200};summon.role=EntityRole::Summon;summon.summoner_id="A";owner.stats.block=0;boss.stats.block=0;BattleRules rules;rules.combat_model=resolution::CombatModel::FunnelV1;Battle summoned({owner,summon,boss},rules);auto death=summoned.apply({"B",ActionType::Attack,"A"});check(death.accepted()&&summoned.phase()==Phase::Finished&&summoned.find("S")->health==0&&std::ranges::any_of(death.events,[](const Event& e){return e.type==EventType::SummonRemoved;}),"summon removed; cannot prevent defeat");
 auto immune=config();immune.attempt_id="immune";immune.roster[1].max_health=10000;EffectDefinition stun{EffectKind::Stun,0,2};stun.irresistible=true;immune.rules.skills={{"stun","A",0,TargetRule::Enemy,{stun}}};PveEncounter protectedBoss(immune,ledger);check(protectedBoss.apply({"A",ActionType::Skill,"B","stun"}).action.accepted()&&!has_status(*protectedBoss.battle().find("B"),EffectKind::Stun),"boss hard-control immunity");
 Status orphan{EffectKind::Bleed,2,TickPolicy::EveryTurn,0,50};orphan.source_id="old-squad";orphan.source_team=Team::A;Definition a{"A",Team::A,1000,1,90},b{"B",Team::B,1000,1,200};Battle carried({a,b},rules,{},{{"B",200,{orphan},{}}});check(carried.find("B")->health==950&&carried.initial_events().front().actor=="old-squad","detached source snapshot supported");
 std::vector<SquadDefinition> squads;for(int i=1;i<=3;++i){BattleRules local;local.combat_model=resolution::CombatModel::FunnelV1;local.action_budget=ActionBudget{1,LimitOutcome::DefeatA};Definition member{"P"+std::to_string(i),Team::A,100,10,100};member.stats.block=0;squads.push_back({"squad"+std::to_string(i),{{member.id,member}},local});}Definition sequenceBoss{"boss",Team::B,1000,1,90};sequenceBoss.stats.block=0;ScoreSequence sequence(SequentialDefinition{"sequence",1,squads,sequenceBoss,BossRuntimeCarry::KeepCooldownsClearStatuses},"seq-attempt",ledger);for(int i=1;i<=3;++i){auto step=sequence.apply({"P"+std::to_string(i),ActionType::Attack,"boss"});check(step.action.accepted(),"sequence one participation");}check(sequence.finished()&&sequence.score()==30,"three squads scored, no cyclic return");
 std::cout<<"REG_PVE_TESTS_RESULT passed=7 total=7\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
